 document.addEventListener('jorsid:language-changed',event=>{localizeOptions();const hidden=document.getElementById('customer_language');if(hidden)hidden.value=event.detail?.language||document.documentElement.lang||'de'}); localizeOptions();const languageField=document.getElementById('customer_language');if(languageField)languageField.value=document.documentElement.lang||'de';
 function update() {
   const option = service.options[service.selectedIndex];
