   const lang=document.documentElement.lang||'de'; const from=lang==='fr'?'À partir de ':lang==='en'?'From ':'Ab '; document.getElementById('summary-price').textContent = selected ? (option.dataset.priceFrom === '1' ? from : '') + money(price) : '—';
