 }
 document.addEventListener('jorsid:language-changed',update);
 async function refreshTravelQuote(){const id=++quoteRequest;const option=service.options[service.selectedIndex];const home=(radios.find(r=>r.checked)?.value==='home');if(!home||!option?.value){currentTravelFee=0;update();const m=document.getElementById('travel-zone-message');if(m)m.textContent='Le tarif de déplacement dépend de la zone.';return;}const city=document.getElementById('city').value.trim(), postal=document.getElementById('postal_code').value.trim();if(!city&&!postal){currentTravelFee=Number(option.dataset.fee||0);update();return;}try{const u=new URL(@json(route('booking.travel-quote')),window.location.origin);u.searchParams.set('service_id',option.value);u.searchParams.set('city',city);u.searchParams.set('postal_code',postal);const response=await fetch(u,{headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('quote');const data=await response.json();if(id!==quoteRequest)return;currentTravelFee=Number(data.fee||0);update();const m=document.getElementById('travel-zone-message');if(m)m.textContent=data.matched?('Zone : '+data.zone+' · tarif de déplacement appliqué.'):'Zone non configurée : tarif indicatif de la prestation, à confirmer par Kessy.';}catch(e){if(id===quoteRequest){currentTravelFee=Number(option.dataset.fee||0);update();}}}
 service.addEventListener('change',()=>{currentTravelFee=0;update();refreshTravelQuote()});
 radios.forEach(r => r.addEventListener('change',()=>{update();refreshTravelQuote()}));
 ['city','postal_code'].forEach(id=>document.getElementById(id).addEventListener('change',refreshTravelQuote));
 update();
 const dateInput=document.getElementById('appointment_date'); const timeSelect=document.getElementById('appointment_time'); const slotMessage=document.getElementById('slot-message');
 const calendar=document.getElementById('booking-calendar'), monthLabel=document.getElementById('calendar-month-label'), daysHost=document.getElementById('calendar-days'), weekdaysHost=document.getElementById('calendar-weekdays'), selectedDateLabel=document.getElementById('calendar-selected-date');
 const minDate=calendar.dataset.minDate;let selectedDate=dateInput.value||'';let monthCursor=selectedDate?new Date(selectedDate+'T12:00:00'):new Date();monthCursor.setDate(1);let availableDates=null;let availabilityMonth='';let availabilityRequest=0;
 function renderCalendar(){const lang=document.documentElement.lang||'de';const locale=lang==='fr'?'fr-FR':lang==='en'?'en-GB':'de-DE';monthLabel.textContent=new Intl.DateTimeFormat(locale,{month:'long',year:'numeric'}).format(monthCursor);weekdaysHost.innerHTML='';['Mo','Di','Mi','Do','Fr','Sa','So'].forEach((w,i)=>{const el=document.createElement('span');el.textContent=(lang==='fr'?['Lu','Ma','Me','Je','Ve','Sa','Di']:lang==='en'?['Mo','Tu','We','Th','Fr','Sa','Su']:['Mo','Di','Mi','Do','Fr','Sa','So'])[i];weekdaysHost.appendChild(el)});daysHost.innerHTML='';const first=new Date(monthCursor.getFullYear(),monthCursor.getMonth(),1);const offset=(first.getDay()+6)%7;const count=new Date(monthCursor.getFullYear(),monthCursor.getMonth()+1,0).getDate();for(let i=0;i<offset;i++){const blank=document.createElement('span');daysHost.appendChild(blank)}for(let day=1;day<=count;day++){const date=new Date(monthCursor.getFullYear(),monthCursor.getMonth(),day);const value=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const b=document.createElement('button');b.type='button';b.className='calendar-day';b.textContent=String(day);b.dataset.date=value;b.disabled=value<minDate;b.title=new Intl.DateTimeFormat(locale,{dateStyle:'full'}).format(date);const currentMonth=monthCursor.getFullYear()+'-'+String(monthCursor.getMonth()+1).padStart(2,'0');if(value>=minDate){if(!service.value){b.classList.add('is-closed');b.disabled=true;b.title+=' · '+(lang==='fr'?'Choisissez une prestation':lang==='en'?'Choose a service':'Bitte Leistung wählen')}else if(availabilityMonth===currentMonth&&availableDates){if(availableDates.has(value)){b.classList.add('is-available');b.title+=' · '+(lang==='fr'?'Disponible':lang==='en'?'Available':'Verfügbar')}else{b.classList.add('is-closed');b.disabled=true}}else if(availabilityMonth===currentMonth){b.classList.add('is-closed');b.disabled=true}}if(value===selectedDate)b.classList.add('is-selected');if(value===new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0'))b.classList.add('is-today');b.addEventListener('click',()=>{selectedDate=value;dateInput.value=value;renderCalendar();updateSelectedDate();loadSlots()});daysHost.appendChild(b)}document.getElementById('calendar-prev').disabled=monthCursor.getFullYear()<Number(minDate.slice(0,4))||(monthCursor.getFullYear()===Number(minDate.slice(0,4))&&monthCursor.getMonth()<=Number(minDate.slice(5,7))-1);}
 async function loadMonthAvailability(){const sid=service.value;const month=monthCursor.getFullYear()+'-'+String(monthCursor.getMonth()+1).padStart(2,'0');if(!sid){availableDates=null;availabilityMonth='';renderCalendar();return}const id=++availabilityRequest;availableDates=null;availabilityMonth=month;renderCalendar();try{const url=new URL(@json(route('booking.month-slots')),window.location.origin);url.searchParams.set('service_id',sid);url.searchParams.set('month',month);url.searchParams.set('mode',radios.find(r=>r.checked)?.value||'salon');const response=await fetch(url,{headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('availability');const data=await response.json();if(id!==availabilityRequest)return;availableDates=new Set(data.available_dates||[]);availabilityMonth=month;if(selectedDate&&selectedDate.startsWith(month)&&!availableDates.has(selectedDate)){selectedDate='';dateInput.value='';timeSelect.innerHTML='<option value="">Choisir une heure</option>';updateSelectedDate()}renderCalendar()}catch(e){if(id===availabilityRequest){availableDates=new Set();availabilityMonth=month;renderCalendar()}}}
 function updateSelectedDate(){if(!selectedDate){selectedDateLabel.textContent=document.documentElement.lang==='de'?'Bitte wählen Sie ein Datum.':document.documentElement.lang==='en'?'Choose a date in the calendar.':'Sélectionnez une date dans le calendrier.';return}const locale=document.documentElement.lang==='fr'?'fr-FR':document.documentElement.lang==='en'?'en-GB':'de-DE';selectedDateLabel.textContent=new Intl.DateTimeFormat(locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(selectedDate+'T12:00:00'));}
 document.getElementById('calendar-prev').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()-1);loadMonthAvailability()});document.getElementById('calendar-next').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()+1);loadMonthAvailability()});document.addEventListener('jorsid:language-changed',()=>{renderCalendar();updateSelectedDate()});renderCalendar();updateSelectedDate();
 let slotRequest=0;async function loadSlots(){const requestId=++slotRequest;const lang=document.documentElement.lang||'de';const messages={de:{loading:'Verfügbare Zeiten werden geladen…',choose:'Leistung und Datum auswählen',hint:'Die Zeiten werden anhand von Kessys Kalender berechnet.',pick:'Uhrzeit auswählen',none:'Keine freien Termine an diesem Tag. Bitte wählen Sie ein anderes Datum.',available:n=>`${n} verfügbare Zeitfenster für die Dauer dieser Leistung.`,error:'Verfügbarkeiten konnten nicht geladen werden. Bitte erneut versuchen.'},fr:{loading:'Chargement des créneaux…',choose:'Choisir une prestation et une date',hint:'Les horaires sont calculés depuis le calendrier de Kessy.',pick:'Choisir un créneau',none:'Aucun créneau libre ce jour-là. Essayez une autre date.',available:n=>`${n} créneau(x) disponible(s) pour la durée de cette prestation.`,error:'Impossible de charger les disponibilités. Réessayez.'},en:{loading:'Loading available times…',choose:'Choose a service and date',hint:"Times are calculated from Kessy's calendar.",pick:'Choose a time',none:'No available slots on this day. Please try another date.',available:n=>`${n} available slot(s) for this service duration.`,error:'Could not load availability. Please try again.'}}[lang];const sid=service.value;const date=dateInput.value;const mode=radios.find(r=>r.checked)?.value||'salon';timeSelect.innerHTML='';const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=messages.loading;timeSelect.appendChild(placeholder);if(!sid||!date){placeholder.textContent=messages.choose;slotMessage.textContent=messages.hint;timeSelect.disabled=false;return;}try{const url=new URL(timeSelect.dataset.slotsUrl,window.location.origin);url.searchParams.set('service_id',sid);url.searchParams.set('date',date);url.searchParams.set('mode',mode);const response=await fetch(url,{headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('availability');const data=await response.json();if(requestId!==slotRequest)return;if(!Array.isArray(data.slots))throw new Error('availability');timeSelect.innerHTML='';const first=document.createElement('option');first.value='';first.textContent=data.slots.length?messages.pick:messages.none;timeSelect.appendChild(first);data.slots.forEach(slot=>{const option=document.createElement('option');option.value=slot;option.textContent=slot;timeSelect.appendChild(option)});slotMessage.textContent=data.slots.length?messages.available(data.slots.length):messages.none;timeSelect.disabled=false;}catch(e){if(requestId!==slotRequest)return;timeSelect.disabled=false;timeSelect.innerHTML='<option value="">'+messages.error+'</option>';slotMessage.textContent=messages.error}}
